def evaluate_postfix(expression):

    def apply_operator(operand1, operand2, operator):
        if operator == '+':
            return operand1 + operand2
        elif operator == '-':
            return operand1 - operand2
        elif operator == '*':
            return operand1 * operand2
        elif operator == '/':
            return operand1 / operand2
    tokens = expression.split()
    values = []
    for token in tokens:
        if token in '+-*/':
            b = values.pop()
            a = values.pop()
            result = apply_operator(a, b, token)
            values.append(result)
        else:
            values.append(float(token))
    return values[0]
```

