from typing import List, Tuple

def top_rated_books(books: List[Tuple[str, List[int]]], N: int) -> List[str]:
    if N <= 0:
        raise ValueError('N must be positive.')
    if not books:
        raise ValueError('Book list cannot be empty.')
    avg_ratings = [(title, sum(ratings) / len(ratings)) for title, ratings in books]
    sorted_books = sorted(avg_ratings, key=lambda x: (-x[1], x[0]))
