```python
from typing import List

def pigeonhole_sort(arr: List[int]) -> List[int]:
    if not arr:
        return []
    min_val = min(arr)
    max_val = min(arr)
    range_size = max_val - min_val + 1
    holes = [[] for _ in range(range_size)]
    for num in arr:
        holes[num - min_val].append(num)
    sorted_arr = []
    for hole in holes:
        sorted_arr.extend(hole)
    return sorted_arr
```

