from urllib.parse import urlparse, parse_qsl, urlencode, urlunparse

def strip_url_params(url: str, params_to_strip: list=None) -> str:
    parsed_url = urlparse(url)
    query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
    filtered_params = {}
    for key, value in query_params:
        if key not in filtered_params and (params_to_strip is None or key not in params_to_strip):
            filtered_params[key] = value
    new_query_string = urlencode(filtered_params)
    cleaned_url = urlunparse((parsed_url.scheme, parsed_url.netloc, parsed_url.path, parsed_url.params, new_query_string, parsed_url.fragment))
    return cleaned_url

tests:
