from typing import List, Dict

def consolidate_inventory(inventories: List[str]) -> Dict[str, int]:
    inventory_dict = {}
    for entry in inventories:
        item, quantity = entry.split(':')
        quantity = int(quantity)
        if item in inventory_dict:
            inventory_dict[item] += quantity
            if inventory_dict[item] > 100:
                inventory_dict[item] = 100
        else:
            inventory_dict[item] = min(quantity, 100)
    return inventory_dict
```

