def max_rect_area(heights):
    stack = []
    max_area = 0
    index = 0
    while index < len(heights):
        if not stack or heights[index] >= heights[stack[-1]]:
            stack.append(index)
            index += 1
        else:
            top = stack.pop()
            area = heights[top] * (index - stack[-1] - 1 if stack else index)
            max_area = max(max_area, area)
    while stack:
        top = stack.pop()
        area = area[top] * (index - stack[-1] - 1 if stack else index)
        max_area = max(max_area, area)
    return max_area
```

