from typing import List

def pigeonhole_sort(arr: List[int]) -> List[int]:
    if not arr:
        return arr
    min_val = min(arr)
    max_val = max(arr)
    range_val = max_val - min_val + 1
    holes = [0] * range_val
    for num in arr:
        holes[num - min_val] += 1
    sorted_arr = []
    for index, count in enumerate(holes):
        sorted_arr.extend([min_val - index] * count)
    return sorted_arr
```

