from typing import Dict, Any, List

def prims_minimum_spanning(graph: Dict[Any, List[List[int]]]) -> int:
    start_node = next(iter(graph))
    pq = [(weight, start_node, to) for weight, to in graph[start_node]]
    heapq.heapify(pq)
    in_mst = set([start_node])
    total_weight = 0
    while pq:
        weight, frm, to = heapq.heappop(pq)
        if to not in in_mst:
            in_mst.add(to)
            total_weight += weight
            total_weight += weight
            for next_weight, next_to in graph[to]:
                if next_to not in in_mst:
                    heapq.heappush(pq, (next_weight, to, next_to))
    return total_weight
