from collections import defaultdict, deque

def find_hierarchy_depth(n, m, connections):
    if n == 1:
        return 1
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)
    for u, v in connections:
        graph[u].append(v)
        in_degree[v] += 1
    top_level_managers = [i for i in range(1, n + 1) if in_degree[i] == 0]

    def bfs_top_level_manager(manager):
        queue = deque([(manager, 1)])
        max_depth = 0
        while queue:
            current, depth = queue.popleft()
            max_depth = max(max_depth, depth)
            for subordinate in graph[current]:
                queue.append((subordinate, depth + 1))
        return max_depth
    max_hierarchy_depth = 0
    for manager in top_level_managers:
        max_hierarchy_depth = max(max_hierarchy_depth, bfs_top_level_manager(manager))
    return max_hierarchy_depth

