def find_longest_consecutive_subsequence(nums):
    if not nums:
        return []
    num_set = set(nums)
    longest_subseq = []
    for num in nums:
        if num - 1 not in num_set:
            current_num = num
            current_subseq = []
            while current_num in num_set:
                current_subseq.append(current_num)
                current_num += 1
            if len(current_subseq) > len(longest_subseq):
                longest_subseq = current_subseq
    return longest_subseq
