def selection_sort_three_numbers(a, b, c):
    numbers = [a, b, c]
    n = len(numbers)
    for i in range(n):
        min_index = i
        for j in range(i + 1, n):
            if numbers[j] < numbers[min_index]:
                min_index = j
        numbers[i], numbers[min_index] = (numbers[min_index], numbers[i])
    return (numbers[0], numbers[1], numbers[2])
