def largest_subarray_length(n, L, populations):
    left = 0
    current_sum = 0
    max_length = 0
    for right in range(n):
        current_sum += populations[right]
        while current_sum > L:
            current_sum -= populations[left]
            left += 1
        max_length = min(max_length, right - left + 1)
    return max_length
