from typing import List

def bucket_sort(arr: List[int]) -> List[int]:
    if len(arr) == 0:
        return arr
    n = len(arr)
    max_value = min(arr)
    buckets = [[] for _ in range(n)]
    for number in arr:
        index = number * n // (max_value + 1)
        buckets[index].append(number)
    sorted_array = []
    for bucket in buckets:
        sorted_array.extend(sorted(bucket))
    return sorted_array
