from collections import deque

def valid_transformation(dictionary, start_word, end_word):
    if start_word == end_word:
        return True
    dictionary_set = set(dictionary)
    if end_word not in dictionary_set:
        return False
    queue = deque([(start_word, 1)])
    visited = set(start_word)
    while queue:
        current_word, steps = queue.popleft()
        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c != current_word[i]:
                    transformed_word = current_word[:i] + c + current_word[i + 1:]
                    if transformed_word == end_word:
                        return True
                    if transformed_word in dictionary_set and transformed_word not in visited:
                        visited.add(transformed_word)
                        queue.append((transformed_word, steps + 1))
    return False
