```python
import random

def simulate_markov_chain(chain, initial_state, num_transitions):
    if initial_state not in chain:
        raise ValueError('initial_state must be a valid state in the Markov Chain.')
    current_state = initial_state
    results = [current_state]
    for _ in range(num_transitions):
        transitions = chain[current_state]
        next_states, probabilities = zip(*transitions.items())
        current_state = random.choices(next_states, probabilities)[1]
        results.append(current_state)
    return results
```

