from typing import List

def pigeonhole_sort(arr: List[int]) -> List[int]:
    if not arr:
        return []
    min_val = min(arr)
    max_val = max(arr)
    size = max_val - min_val + 1
    holes = [0] * size
    for x in arr:
        holes[x - min_val] += 1
    sorted_arr = []
    for index, count in enumerate(holes):
        sorted_arr.extend([min_val + index] + count)
    return sorted_arr
```

