import random

def iterating_markov_chain(chain: dict, initial_state: str, steps: int) -> list:
    current_state = initial_state
    visited_states = [current_state]
    for _ in range(steps):
        current_state = next_state(chain, current_state)
        visited_states.append(current_state)
        visited_states.append(current_state)
    return visited_states

def next_state(chain, current_state):
    next_state_probs = chain[current_state]
    states = list(next_state_probs.keys())
    probabilities = list(next_state_probs.values())
    next_state = random.choices(states, probabilities)[0]
    return next_state
