def dual_pivot_partition(arr, low, high):
    if arr[low] > arr[high]:
        arr[low], arr[high] = (arr[high], arr[low])
    lp = low + 1
    rp = high - 1
    k = low + 1
    p = arr[low]
    q = arr[high]
    while k <= rp:
        if arr[k] < p:
            arr[k], arr[lp] = (arr[lp], arr[k])
            lp += 1
        elif arr[k] >= q:
            while arr[rp] > q and k < rp:
                rp -= 1
            arr[k], arr[rp] = (arr[rp], arr[k])
            rp -= 1
            if arr[k] < p:
                arr[k], arr[lp] = (arr[lp], arr[k])
                lp += 1
        k += 1
    lp -= 1
    rp += 1
    arr[low], arr[lp] = (arr[lp], arr[low])
    arr[high], arr[rp] = (arr[rp], arr[high])
