def productExceptSelf(arr, N):
    prefix_products = [1] * N
    suffix_products = [1] * N
    output = [1] * N
    for i in range(1, N):
        prefix_products[i] = prefix_products[i - 1] * arr[i - 1]
    for i in range(N - 2, -1, -1):
        suffix_products[i] = suffix_products[i + 1] * arr[i + 1]
    for i in range(N):
        output[i] = prefix_products[i] * suffix_products[i]
    return output
