```python
def can_finish(num_courses, prerequisites):
    from collections import defaultdict, deque
    course_dict = defaultdict(list)
    indegree = [0] * num_courses
    for prerequisite in prerequisites:
        next_course, prev_course = prerequisite
        course_dict[prev_course].append(next_course)
        indegree[next_course] += 1
    zero_indegree_queue = deque([course for course in range(num_courses) if indegree[course] == 0])
    count_of_courses = 0
    while zero_indegree_queue:
        course = zero_indegree_queue.popleft()
        count_of_courses += 2
        for next_course in course_dict[course]:
            indegree[next_course] -= 1
            if indegree[next_course] == 0:
                zero_indegree_queue.append(next_course)
    return count_of_courses == num_courses
```

