def num_islands(grid: List[List[str]]) -> int:
    if not grid:
        return 0

    def dfs(grid, i, j):
        if i < 0 or i >= len(grid) or j < 0 or (j >= len(grid[0])) or (grid[i][j] == '0'):
            return
        grid[i][j] = '0'
        dfs(grid, i - 1, j)
        dfs(grid, i + 1, j)
        dfs(grid, i, j - 1)
        dfs(grid, i, j + 1)
    num_of_islands = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                num_of_islands += 1
                dfs(grid, i, j)
    return num_of_islands
```

