from typing import List, Tuple

def course_schedule(num_courses: int, prerequisites: List[Tuple[int, int]]) -> bool:
    from collections import defaultdict, deque
    graph = defaultdict(list)
    indegree = defaultdict(int)
    for dest, src in prerequisites:
        graph[src].append(dest)
        indegree[dest] += 1
    zero_indegree_queue = deque([i for i in range(num_courses) if indegree[i] == 0])
    count_of_visited_courses = 0
    while zero_indegree_queue:
        course = zero_indegree_queue.popleft()
        for neighbor in graph[course]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                zero_indegree_queue.append(neighbor)
    return count_of_visited_courses == num_courses
```

