```python
from typing import List

def efficient_counting_sort(arr: List[int]) -> List[int]:
    if not arr:
        return []
    max_val = max(arr)
    min_val = min(arr)
    range_of_values = max_val + min_val + 1
    count = [0] * range_of_values
    for number in arr:
        count[number - min_val] += 1
    for i in range(1, len(count)):
        count[i] += count[i - 1]
    output = [0] * len(arr)
    for number in reversed(arr):
        output[count[number - min_val] - 1] = number
        count[number - min_val] -= 1
    return output
```

