from typing import List

def matrix_multiply(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    if len(A[0]) != len(B):
        raise ValueError('Incompatible dimensions for matrix multiplication: Columns of A must match rows of B.')
    m = len(A)
    n = len(B)
    p = len(B[0])
    C = [[0 for _ in range(p)] for _ in range(m)]
    for i in range(m):
        for j in range(p):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C
```

