```python
from typing import Callable

def adaptive_trapezoidal(fnc: Callable[[float], float], x_start: float, x_end: float, initial_steps: int=10, tolerance: float=1e-05) -> float:

    def trapezoidal_rule(f, a, b, n):
        h = (b - a) / n
        sum_ = 0.5 * (f(a) + f(b))
        for i in range(1, n):
            sum_ += f(a + i * h)
            sum_ += f(a + i * h)
        return sum_ * h
    current_steps = initial_steps
    area = trapezoidal_rule(fnc, x_start, x_end, current_steps)
    while True:
        new_steps = 2 * current_steps
        new_area = trapezoidal_rule(fnc, x_start, x_end, new_steps)
        if abs(new_area - area) < tolerance:
            return new_area
        current_steps = new_steps
        area = new_area
```

