    graph = defaultdict(list)
    for u, v in edges:
        graph[u].extend(v)
        in_degree[v] += 1
    min_heap = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(min_heap, i)
    topological_order = []
    while min_heap:
        u = heapq.heappop(min_heap)
        topological_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(min_heap, v)
    return topological_order if len(topological_order) == n else []
