from typing import List

def modified_bucket_sort(arr: List[float]) -> List[float]:
    if not arr:
        return []
    n = len(arr)
    buckets = [[] for _ in range(n)]
    for value in arr:
        index = int(n * value)
        buckets[index].append(value)
    for bucket in buckets:
        bucket.sort()
    sorted_arr = []
    for bucket in buckets:
        sorted_arr.extend(bucket)
