def smallest_n_numbers(arr, n):

    def bubble_sort(arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n - i - 1):
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = (arr[j + 1], arr[j])
    if n >= len(arr):
        bubble_sort(arr)
        return arr
    smallest_numbers = []
    for _ in range(n):
        min_value = min(arr)
        smallest_numbers.append(min_value)
        arr.remove(min_value)
    bubble_sort(smallest_numbers)
    return smallest_numbers
```

