from typing import List

def search_insert(sorted_part: List[int], value: int) -> int:
    for i in range(len(sorted_part)):
        if value < sorted_part[i]:
            return i
    return len(sorted_part)

def insertion_sort(array: List[int]) -> List[int]:
    sorted_array = []
    for value in array:
        pos = search_insert(sorted_array, value)
        sorted_array.insert(pos, value)
    return sorted_array
