def optimized_counting_sort(arr):
    if not arr:
        return arr
    min_val = min(arr)
    max_val = max(arr)
    count_range = max_val - min_val + 1
    count = [0] * count_range
    for num in arr:
        count[num - min_val] += 1
    for i in range(1, count_range):
        count[i] -= count[i - 1]
    result = [0] * len(arr)
    for num in reversed(arr):
        index = count[num - min_val] - 1
        result[index] = num
        count[num - min_val] -= 1
    return result
