from typing import List

def optimized_shell_sort(arr: List[int]) -> List[int]:

    def hibbard_gaps(size):
        k = 1
        gaps = []
        while (1 << k) - 1 < size:
            gaps.append((1 << k) - 1)
            k += 1
        return gaps[::-1]
    n = len(arr)
    gaps = hibbard_gaps(n)
    for gap in gaps:
        for i in range(gap, n):
            temp = arr[i]
            j = i
            while j >= gap and arr[j - gap] > temp:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = temp
    return arr

