        array[low], array[end] = (array[end], array[low])
        if low == rank:
            return array[low]
        elif low < rank:
            return quickselect(low + 1, end, rank)
        else:
            return quickselect(start, low - 1, rank)
    array_copy = array[:]
    return quickselect(0, len(array_copy) - 1, k - 1)
