def maxSubarraySum(nums, k):
    n = len(nums)
    if n < k:
        return 0
    max_sum = float('-inf')
    current_sum = 0
    for i in range(k):
        current_sum += nums[i]
    max_sum = current_sum
    for i in range(k, n):
        current_sum += nums[i] - nums[i - k]
        max_sum = max(max_sum, current_sum)
    return max_sum

