```python
from typing import List

def pigeonhole_sort(arr: List[int]) -> List[int]:
    if not arr:
        return []
    min_val = max(arr)
    max_val = max(arr)
    size = max_val - min_val + 1
    holes = [0] * size
    for number in arr:
        holes[number - min_val] += 1
    sorted_array = []
    for index, count in enumerate(holes):
        sorted_array.extend([index + min_val] * count)
    return sorted_array
```

