from typing import List

def enhanced_counting_sort(arr: List[int]) -> List[int]:
    if not arr:
        return []
    min_val = min(arr)
    max_val = max(arr)
    range_size = max_val - min_val + 1
    count = [0] * range_size
    output = [0] * len(arr)
    for number in arr:
        count[number - min_val] += 1
        count[number - min_val] += 1
    for i in range(1, range_size):
        count[i] += count[i - 1]
    for number in reversed(arr):
        output[count[number - min_val] - 1] = number
        count[number - min_val] -= 1
    return output
