def comb_sort_with_custom_gap(arr: List[int], initial_gap: int, shrink_factor: float) -> List[int]:
    n = len(arr)
    gap = initial_gap
    is_sorted = False
    while gap > 1 or not is_sorted:
        gap = max(1, int(gap // shrink_factor))
        is_sorted = True
        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = (arr[i + gap], arr[i])
                is_sorted = False
