def calculate_grades(students: dict) -> dict:

    def get_grade(average):
        if 90 <= average <= 100:
            return 'A'
        elif 80 <= average < 90:
            return 'B'
        elif 70 <= average < 80:
            return 'C'
        elif 60 <= average < 70:
            return 'D'
        else:
            return 'F'
    final_grades = {}
    for student, subjects in students.items():
        if subjects:
            average = sum(subjects.values()) / len(subjects)
            final_grades[student] = get_grade(average)
    return final_grades
