def isBipartite(adjList):
    color = {}

    def dfs(node, current_color):
        if node in color:
            return color[node] == current_color
        color[node] = current_color
        return all((dfs(neigh, 1 - current_color) for neigh in adjList[node]))
    return all((dfs(node, 0) for node in range(len(adjList)) if node not in color))
```

