def compute_nCr(n: int, r: int) -> int:
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n - r:
        r = n - r
    dp = [0] * (r + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(min(i, r), 0, -1):
            dp[j] = dp[j] + dp[j - 1]
    return dp[r]
```

