def search_insert(sorted_sublist: List[int], x: int) -> int:
    low, high = (0, len(sorted_sublist))
    while low < high:
        mid = (low + high) // 2
        if sorted_sublist[mid] < x:
            low = mid + 1
        else:
            high = mid
    return low

def insertion_sort(arr: List[int]) -> List[int]:
    sorted_arr = []
    for x in arr:
        pos = search_insert(sorted_arr, x)
        sorted_arr.insert(pos, x)
    return sorted_arr
