def rotate_matrix(matrix: list[list[int]], direction: str) -> list[list[int]]:
    n = len(matrix)
    rotated = [[0] * n for _ in range(n)]
    if direction == 'clockwise':
        for i in range(n):
            for j in range(n):
                rotated[j][n - 1 - i] = matrix[i][j]
    elif direction == 'counterclockwise':
        for i in range(n):
            for j in range(n):
                rotated[n - 1 - j][i] = matrix[i][j]
    else:
        raise ValueError("Invalid direction. It should be either 'clockwise' or 'counterclockwise'")
    return rotated
