    result = []
    iterators = [iter(lst) for lst in lists]
    for i, it in enumerate(iterators):
        first_movie = next(it, None)
        if first_movie is not None:
            heapq.heappush(min_heap, (first_movie, i))
    while min_heap:
        movie, i = heapq.heappop(min_heap)
        result.append(movie)
        next_movie = next(iterators[i], None)
        if next_movie is not None:
            heapq.heappush(min_heap, (next_movie, i))
