from collections import deque

def sliding_window_maximum(n, temperatures, k):
    if n <= 0 or k <= 0 or k > n:
        return []
    dq = deque()
    result = []
    for i in range(n):
        while dq and dq[0] <= i - k:
            dq.popleft()
        while dq and temperatures[dq[-1]] <= temperatures[i]:
            dq.pop()
        dq.append(i)
        if i >= k - 1:
            result.append(temperatures[dq[0]])
    return result

