def can_deliver(n, m, k, s, d, roads):
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, l in roads:
        graph[u].append((v, l))
    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[s] = 0
    priority_queue = [(0, s)]
    while priority_queue:
