def largest_balanced_subarray_len(arr):
    n = len(arr)
    balance_map = {0: -1}
    even_count = 0
    odd_count = 0
    max_len = 0
    for i in range(n):
        if arr[i] % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
        balance = even_count - odd_count
        if balance in balance_map:
            max_len = max(max_len, i - balance_map[balance])
        else:
            balance_map[balance] = i
    return max_len

