from typing import List

def pigeonhole_sort(arr: List[int]) -> List[int]:
    if not arr:
        return arr
    min_val = min(arr)
    max_val = max(arr)
    Range = max_val - min_val + 1
    holes = [0] * Range
    for number in arr:
        holes[number - min_val] += 1
