def is_bipartite(graph):
    color = {}

    def dfs(node, c):
        if node in color:
            return color[node] == c
        color[node] = c
        return all((dfs(nei, c ^ 1) for nei in graph[node]))
    return all((dfs(node, 0) for node in range(len(graph)) if node not in color))
```

