def calculate_results(scores):
    results = {}
    for score in scores:
        teams_and_scores = score.split(':')
        teams = teams_and_scores[0].split(' vs ')
        scores = list(map(int, teams_and_scores[1].split('-')))
        team_a, team_b = teams
        score_a, score_b = scores
        if team_a not in results:
            results[team_a] = {'wins': 0, 'losses': 0, 'draws': 0}
        if team_b not in results:
            results[team_b] = {'wins': 0, 'losses': 0, 'draws': 0}
        if score_a > score_b:
            results[team_a]['wins'] += 1
            results[team_b]['losses'] += 1
        elif score_a < score_b:
            results[team_a]['losses'] += 1
            results[team_b]['wins'] += 1
