from collections import Counter, defaultdict
import heapq

def top_k_frequent_elements(nums: List[int], k: int) -> List[int]:
    freq_counter = Counter(nums)
    order_dict = {}
    for idx, num in enumerate(nums):
        if num not in order_dict:
            order_dict[num] = idx
    heap = [(-count, order_dict[num], num) for num, count in freq_counter.items()]
    heapq.heapify(heap)
    top_k = [heapq.heappop(heap)[2] for _ in range(k)]
