from typing import List

def numIslands2(m: int, n: int, coordinates: List[List[int]]) -> List[int]:

    def find(parent, i):
        if parent[i] != i:
            parent[i] = find(parent, parent[i])
        return parent[i]

    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1
    if not coordinates:
        return []
    parent = {}
    rank = {}
    grid = [[0 for _ in range(n)] for _ in range(m)]
    num_islands = 0
    result = []
    for x, y in coordinates:
        if grid[x][y] == 1:
            result.append(num_islands)
            continue
        grid[x][y] = 1
        index = x * n + y
        parent[index] = index
        rank[index] = 0
        num_islands += 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = (x + dx, y + dy)
            if 0 <= nx < m and 0 <= ny < n and (grid[nx][ny] == 1):
                neighbor_index = nx * n + ny
                if find(parent, index) != find(parent, neighbor_index):
                    union(parent, rank, index, neighbor_index)
                    num_islands -= 1
        result.append(num_islands)
    return result

