def is_valid_sequence(s: str) -> bool:
    stack = []
    closing_to_opening = {')': '(', '}': '{', ']': '['}
    for character in s:
        if character in closing_to_opening.values():
            stack.append(character)
        elif character in closing_to_opening.keys():
            if not stack or stack.pop() != closing_to_opening[character]:
                return False
    return len(stack) == 0
