def max_water_trapped(heights):
    if not heights or len(heights) < 3:
        return 0
    left, right = (0, len(heights) - 1)
    left_max, right_max = (heights[left], heights[right])
    water_trapped = 0
    while left < right:
        if heights[left] <= heights[right]:
            left += 1
            left_max = max(left_max, heights[left])
            water_trapped += max(0, left_max - heights[left])
        else:
            right -= 1
            right_max = max(right_max, heights[right])
            water_trapped += max(0, right_max - heights[right])
    return water_trapped

def process_test_cases(T, cases):
    results = []
    for i in range(T):
        N = cases[i][0]
        heights = cases[i][1]
        results.append(max_water_trapped(heights))
    return results

