import heapq
from collections import defaultdict
from typing import List, Tuple, Union

def dijkstra(N: int, M: int, edges: List[Tuple[int, int, int]]) -> List[int]:
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    def shortest_path(start: int) -> List[Union[int, float]]:
        distances = [float('inf')] * (N + 1)
        distances[start] = 0
        pq = [(0, start)]
        while pq:
            current_distance, u = heapq.heappop(pq)
            if current_distance > distances[u]:
                continue
            for v, weight in graph[u]:
                distance = current_distance + weight
                if distance < distances[v]:
                    distances[v] = distance
                    heapq.heappush(pq, (distance, v))
        return distances
    distances_from_1 = shortest_path(1)
    return [dist if dist != float('inf') else -1 for dist in distances_from_1[2:]]

