def max_possible_number(n):
    digit_count = [0] * 10
    num = n
    while num > 0:
        digit = num % 10
        digit_count[digit] += 1
        num //= 10
    max_number = 0
    for digit in range(9, -1, -1):
        while digit_count[digit] > 0:
            max_number = max_number * 10 + digit
            digit_count[digit] -= 1
    return max_number

