def longest_substring_with_k_distinct_chars(s, k):
    if k == 0:
        return 0
    n = len(s)
    left = 0
    right = 0
    max_len = 0
    char_count = {}
    while right < n:
        char = s[right]
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
        while len(char_count) > k:
            left_char = s[left]
            char_count[left_char] -= 1
            if char_count[left_char] == 0:
                del char_count[left_char]
            left += 1
        max_len = max(max_len, right - left + 1)
        right += 1
    return max_len
```

