def integer_divide(dividend: int, divisor: int) -> int:
    if dividend == 0:
        return 0
    negative = (dividend < 0) != (divisor < 0)
    dividend, divisor = (abs(dividend), abs(divisor))
    quotient = 0
    current_sum = divisor
    while dividend >= current_sum:
