fixed_code:
def min_moves(grid_size: tuple, start: tuple, destination: tuple) -> int:
    rows, cols = grid_size
    if rows <= 0 or cols <= 0:
        raise Exception('Grid dimensions must be positive integers')
    start_row, start_col = start
    dest_row, dest_col = destination
    if not (0 <= start_row < rows and 0 <= start_col < cols):
        raise Exception('Start coordinates out of grid boundaries')
    if not (0 <= dest_row < rows and 0 <= dest_col < cols):
        raise Exception('Destination coordinates out of grid boundaries')
    moves = abs(dest_row - start_row) + abs(dest_col - start_col)
    return moves

