from typing import List, Tuple

def analyze_stock_prices(stock_prices: List[int]) -> Tuple[int, int, int]:
    n = len(stock_prices)
    if n < 2:
        return (0, -1, -1)
    min_price_day = 0
    max_profit = 0
    buy_day = -1
    sell_day = -1
    for i in range(1, n):
        if stock_prices[i] < stock_prices[min_price_day]:
            min_price_day = i
        current_profit = stock_prices[i] - stock_prices[min_price_day]
        if current_profit > max_profit:
            max_profit = current_profit
            buy_day = min_price_day
            sell_day = i
    if buy_day == -1 or sell_day == -1:
        return (0, -1, -1)
    return (max_profit, buy_day + 1, sell_day + 1)
