from typing import List

def find_first_occurrence(array: List[int], target: int) -> int:
    low, high = (0, len(array) - 1)
    first_occurrence = -1
    while low <= high:
        mid = (low + high) // 2
        if array[mid] == target:
            first_occurrence = mid
            high = mid - 1
        elif array[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return first_occurrence
```

