import threading

def parallel_sum(numbers: list[int], num_threads: int) -> int:
    if not numbers:
        return 0
    n = len(numbers)
    if num_threads > n:
        num_threads = n
    sums = [0] * num_threads
    threads = []

    def worker(start, end, index):
        part_sum = sum(numbers[start:end])
        sums[index] = part_sum
    chunk_size = (n + num_threads - 1) // num_threads
    for i in range(num_threads):
        start = i * chunk_size
        end = min(start + chunk_size, n)
        thread = threading.Thread(target=worker, args=(start, end, i))
        thread.start()
        threads.append(thread)
    for thread in threads:
        thread.join()
    return sum(sums)
