from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    else:
        return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if xroot != yroot:
        if rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        elif rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

def count_synonym_groups(num_cases, test_cases):
    results = []
    for case in test_cases:
        N = case[0]
        synonym_pairs = case[1]
        M = case[2]
        words = case[3]
        parent = {}
        rank = {}
        for pair in synonym_pairs:
            word1, word2 = pair
            if word1 not in parent:
                parent[word1] = word1
                rank[word1] = 0
            if word2 not in parent:
                parent[word2] = word2
                rank[word2] = 0
            union(parent, rank, word1, word2)
        root_set = set()
        for word in words:
            if word in parent:
                root_set.add(find(parent, word))
            else:
                root_set.add(word)
        results.append(len(root_set))
    return results
